 * Tokenizes either a `String` or an `Array[Byte]`. The Python original is
 * parametric in `StrOrBytes`; the equivalent in Scala is a runtime dispatch
 * since Scala 2.13 has no proper union types.
 */
final class StringTokenizer(
    val encoding: Charset = StandardCharsets.UTF_8,
    normalizer: String => String = identity
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = ***REDACTED***
    val str = value match {
      case s: String      => s
      case b: Array[Byte] => new String(b, encoding)
      case other =>
        throw new IllegalArgumentException(
          s"StringTokenizer expects String or Array[Byte], got ${other.getClass.getName}"
        )
    }
    Token(normalizer(str), TokenType.STRING)
  }
}

object StringTokenizer {
  def apply(
      encoding: Charset = StandardCharsets.UTF_8,
      normalizer: String => String = identity
