    val precision: Int = 6,
    val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = ***REDACTED***
    val (str, originalType) = value match {
      case d: BigDecimal => (formatFractional(d.doubleValue), "BigDecimal")
      case d: Double     => (formatFractional(d), "Double")
      case f: Float      => (formatFractional(f.toDouble), "Float")
      case i: Int        => (i.toString, "Int")
      case l: Long       => (l.toString, "Long")
      case s: Short      => (s.toString, "Short")
      case b: BigInt     => (b.toString, "BigInt")
      case other =>
        throw new IllegalArgumentException(
          s"NumericTokenizer expects a numeric value, got ${other.getClass.getName}"
        )
    }
