// Temporal tokenizer
// ============================================================================

/**
 * Tokenizer for `java.time` temporal values. A `LocalDateTime` is formatted
 * with the ISO date-time pattern, a `LocalDate` with the ISO date pattern,
 * unless a custom pattern is supplied.
 */
final class TemporalTokenizer(val formatPattern: Option[String] = None)
    extends BaseTokenizer[TemporalAccessor] {

  override def tokenize(value: TemporalAccessor): Token = ***REDACTED***
    val formatter = formatPattern match {
      case Some(p) => DateTimeFormatter.ofPattern(p)
      case None => value match {
        case _: LocalDateTime => TemporalTokenizer.IsoFormatter
        case _: LocalDate     => TemporalTokenizer.DateFormatter
        case _                => DateTimeFormatter.ISO_DATE_TIME
      }
    }
    Token(formatter.format(value), TokenType.TEMPORAL)
  }
}

