// ============================================================================
// Universal tokenizer – runtime dispatch over heterogeneous inputs
// ============================================================================

/**
 * Tokenizer that dispatches to the appropriate specialised tokenizer based on
 * the runtime type of the input. Unknown types fall back to `toString`.
 */
final class UniversalTokenizer {
  private val stringTokenizer   = new StringTokenizer()
  private val numericTokenizer  = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = ***REDACTED*** match {
    case null              => Token("NULL", TokenType.NULL)
    case t: Tokenizable    => Token(t.toToken, TokenType.STRUCTURED)
    case s: String         => stringTokenizer.tokenize(s)
    case b: Array[Byte]    => stringTokenizer.tokenize(b)
    case n @ (_: Int | _: Long | _: Short | _: Float | _: Double | _: BigDecimal | _: BigInt) =>
      numericTokenizer.tokenize(n)
    case t: TemporalAccessor => temporalTokenizer.tokenize(t)
    case other =>
      Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }

  /** Lazy batch tokenization matching `BaseTokenizer.tokenizeBatch`. */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] =
    values.iterator.map(tokenize)
}

// ============================================================================
// Whitespace tokenizer – basic text tokenization
// ============================================================================

/**
 * Splits a text on whitespace and emits one token per word, with optional
 * normalisation (lowercasing, punctuation stripping, length constraints).
 */
final class WhitespaceTokenizer(
    val lowercase: Boolean = false,
    val minLength: Int = 0,
    val maxLength: Option[Int] = None,
    val stripPunctuation: Boolean = false
) {
  import WhitespaceTokenizer.Punctuation

  private def processToken(word: String): Option[String] = {
    val stripped  = if (stripPunctuation) word.dropWhile(Punctuation).reverse.dropWhile(Punctuation).reverse else word
    val cased     = if (lowercase) stripped.toLowerCase else stripped
    val truncated = maxLength.filter(cased.length > _).fold(cased)(cased.take)

    if (truncated.isEmpty || truncated.length < minLength) None
    else Some(truncated)
  }

  /** Tokenize into [[Token]] values, preserving the original word and position. */
  def tokenize(text: String): List[Token] =
    text.split("\\s+").iterator
      .filter(_.nonEmpty)
      .zipWithIndex
      .flatMap { case (word, i) =>
        processToken(word).map { v =>
          Token(v, TokenType.STRING, Map("position" -> i, "original" -> word))
        }
      }
      .toList

  /** Convenience: return only the token strings. */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /** Tokenize text and return each token with its (start, end) character offsets. */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val builder = List.newBuilder[(String, Int, Int)]
    var cursor  = 0
    for (word <- text.split("\\s+") if word.nonEmpty) {
      val start = text.indexOf(word, cursor)
      val end   = start + word.length
      processToken(word).foreach(p => builder += ((p, start, end)))
      cursor = end
    }
    builder.result()
  }

  def countTokens(text: String): Int = tokenize(text).size
}

object WhitespaceTokenizer {
  private val Punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet
}

